using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RoomBooking.Infrastructure.Persistence; using RoomBooking.Web.Infrastructure; using System.Text;
namespace RoomBooking.Web.Controllers;
[Authorize(Roles="SuperAdmin,TenantAdmin,Approver")]
public class ReportsController(RoomBookingDbContext db):Controller{public IActionResult Index(){var tenant=HttpContext.TenantId();var rows=db.Reservations.Include(x=>x.MeetingRoom).Where(x=>tenant!=null&&x.CompanyId==tenant&&x.Status!="Cancelled"&&x.Status!="Rejected").ToList();ViewBag.Rows=rows;ViewBag.RoomUsage=rows.GroupBy(x=>x.MeetingRoom!.Name).Select(x=>new{x.Key,Count=x.Count()}).OrderByDescending(x=>x.Count).ToList();return View();}public IActionResult ExportCsv(){var tenant=HttpContext.TenantId();var rows=db.Reservations.Include(x=>x.MeetingRoom).Include(x=>x.User).Where(x=>tenant!=null&&x.CompanyId==tenant).OrderBy(x=>x.StartAt).ToList();var csv=new StringBuilder("Subject,Room,ReservedBy,Start,End,Status\n");foreach(var x in rows)csv.AppendLine($"\"{x.Subject.Replace("\"","\"\"")}\",\"{x.MeetingRoom?.Name}\",\"{x.User?.FullName}\",{x.StartAt:yyyy-MM-dd HH:mm},{x.EndAt:yyyy-MM-dd HH:mm},{x.Status}");return File(Encoding.UTF8.GetBytes(csv.ToString()),"text/csv","roombooking-report.csv");}}
